  /* ---------- writing tasks ---------- */
  var TYPE_JA = { opinion: '意見パラグラフ', complaint: '苦情メール', request: '依頼メール', proposal: '提案メール', report: 'レポート要約', review: 'レビュー', counter: '反論パラグラフ' };
  function T(id, type, titleJa, prompt, ja, plan, useful, model) {
    return { id: id, type: type, typeJa: TYPE_JA[type], titleJa: titleJa, prompt: prompt, ja: ja, plan: plan, useful: useful, model: model };
  }

  var tasks = [
    T('t01', 'opinion', '在宅勤務を標準にすべきか',
      'Some people believe that remote work should become the default for office jobs. Write a paragraph (120–180 words) giving your opinion, with reasons.',
      '事務職では在宅勤務を標準にすべきだと考える人がいます。理由を挙げて、あなたの意見を1段落（120～180語）で書いてください。',
      ['1文目で立場を明示する（賛成・反対・条件付き）', '相手側の利点を1つ認める（Admittedly, ...）', '自分の理由を2つ、具体例とともに述べる', '提案または言い換えた結論で締める'],
      ['I would argue that ...', 'Admittedly, ...', 'a blanket policy', 'A more sensible approach would be to ...', '... would do well to ...'],
      "While remote work is often portrayed as a universal solution, I would argue that it should be an option rather than the default. Admittedly, working from home eliminates commuting and gives employees greater control over their time, which tends to improve both morale and productivity. However, these gains are unevenly distributed. Junior staff, in particular, learn a great deal through informal contact with experienced colleagues, and this kind of learning is difficult to replicate on a screen. Moreover, not everyone has a quiet room or reliable equipment at home, so a blanket policy risks widening the gap between those who can work comfortably and those who cannot. A more sensible approach would be to let teams decide how often they need to meet in person, provided that the arrangement is reviewed regularly. In short, flexibility, not distance, is what makes work better, and companies would do well to treat remote work as one tool among several."),
    T('t02', 'opinion', '大学教育は無償にすべきか',
      'Should university education be free for everyone? Write a paragraph (120–180 words) giving your opinion.',
      '大学教育はすべての人に無償であるべきでしょうか。あなたの意見を1段落（120～180語）で書いてください。',
      ['無償化の理念を認めたうえで自分の立場を示す', '無償化の問題点を1つ、理由とともに説明する', '代案を具体的に示す', 'On balance で結論をまとめる'],
      ['The case for ... rests on ...', 'I have considerable sympathy with this view, yet ...', 'at the expense of ...', 'would arguably ...', 'it does not follow that ...'],
      "The case for free university education rests on a powerful idea: that talent, not family income, should determine who gets a degree. I have considerable sympathy with this view, yet I am not convinced that abolishing fees altogether is the fairest way to achieve it. In practice, students from wealthier backgrounds are still far more likely to attend university, which means that free tuition can end up subsidising those who need help least, at the expense of taxpayers who never went themselves. A more targeted system, in which fees are waived for low-income students and others repay a modest share once they are earning a decent salary, would arguably do more to widen access. Such a scheme would also leave universities with the funding they need to maintain standards. On balance, then, higher education should be affordable for all, but it does not follow that it must be free for all."),
    T('t03', 'opinion', '道路より公共交通に投資すべきか',
      'Is it better for cities to invest in public transport than in new roads? Write a paragraph (120–180 words) giving your opinion.',
      '都市は新しい道路よりも公共交通機関に投資すべきでしょうか。あなたの意見を1段落（120～180語）で書いてください。',
      ['現状（渋滞）に触れてから立場を示す', '道路建設が解決にならない理由を述べる', '反対意見を取り上げ、一部認めて反論する', '優先順位を明確にして締める'],
      ['Experience suggests that ...', 'by contrast', 'Critics may object that ...', 'This is true to some extent; nevertheless, ...', 'That is not to say that ...'],
      "Faced with ever-worsening congestion, many cities instinctively respond by building more roads. In my view, this is a costly mistake, and investment in public transport offers far better value. Experience suggests that new roads tend to fill up almost as soon as they open, since extra capacity simply encourages more people to drive. Reliable trains and buses, by contrast, can move far greater numbers using a fraction of the space, while also cutting emissions and noise. Critics may object that public transport is inflexible and rarely profitable. This is true to some extent; nevertheless, roads are not expected to make a profit either, and their hidden costs, from accidents to air pollution, are borne by everyone. That is not to say that roads should be neglected, as buses and delivery vehicles depend on them too. The priority, however, ought to be clear: cities work best when most journeys do not require a car."),
    T('t04', 'opinion', 'SNSは公共の議論に有害か',
      'Do social media do more harm than good to public debate? Write a paragraph (120–180 words) giving your opinion.',
      'SNSは公共の議論にとって、益よりも害の方が大きいでしょうか。あなたの意見を1段落（120～180語）で書いてください。',
      ['よくある批判を紹介し、一理あると認める', 'That said で視点を転換し、利点を挙げる', '本当の問題がどこにあるかを指摘する', '比喩や言い換えで印象的に締める'],
      ['The charge is not without foundation.', 'That said, ...', 'hold the powerful to account', 'lies less in ... than in ...', 'in other words'],
      "It has become fashionable to blame social media for the poor quality of public debate, and the charge is not without foundation. Platforms reward content that provokes strong emotions, so that outrage travels further than careful reasoning, and users are steadily steered towards opinions they already hold. That said, I believe the overall picture is more nuanced than critics allow. Social media have given a voice to people who were previously ignored by traditional outlets, and they have enabled ordinary citizens to hold the powerful to account with remarkable speed. The real problem, it seems to me, lies less in the technology itself than in the business model behind it, which treats attention as a product to be sold. If platforms were required to be more transparent about how content is promoted, much of the damage could be limited. Social media are, in other words, a flawed public square, but one worth repairing rather than abandoning."),
    T('t05', 'opinion', '勤務時間外の業務連絡',
      'Should employers be allowed to contact staff outside working hours? Write a paragraph (120–180 words) giving your opinion.',
      '雇用主が勤務時間外に従業員へ連絡することは認められるべきでしょうか。あなたの意見を1段落（120～180語）で書いてください。',
      ['背景（スマホ・つながらない権利）と立場を示す', '常時対応がもたらす悪影響を説明する', '例外的な職種という反論を扱う', '結論：例外であって標準ではない'],
      ['I am broadly in favour of ...', 'The evidence suggests that ...', 'It could be argued that ...', 'This is a fair point; however, ...', 'the exception, never the norm'],
      "Thanks to smartphones, the working day no longer ends when employees leave the office, and a growing number of countries now recognise a legal 'right to disconnect'. I am broadly in favour of such measures. Constant availability may look like dedication, but the evidence suggests that it leads to exhaustion and, ultimately, to poorer work. People who never fully switch off tend to make more mistakes and are more likely to resign. It could be argued that some roles, such as those involving emergencies or clients in other time zones, simply cannot follow fixed hours. This is a fair point; however, it calls for clearly defined exceptions and proper compensation rather than an unspoken expectation that everyone should always be reachable. Ultimately, a rule of this kind protects employers as well as staff, since rested employees are more productive. Out-of-hours contact should therefore be the exception, agreed in advance, and never the norm."),
    T('t06', 'opinion', '機械翻訳の時代の外国語学習',
      'Is learning a foreign language still worthwhile now that machine translation is so good? Write a paragraph (120–180 words) giving your opinion.',
      '機械翻訳がこれほど優れている今でも、外国語を学ぶ価値はあるでしょうか。あなたの意見を1段落（120～180語）で書いてください。',
      ['「もう不要だ」という見方を紹介し、立場を示す', '翻訳ソフトの限界を具体的に述べる', '利便性以外の学習の価値を挙げる', '技術を否定せず、対比で締める'],
      ['it is tempting to conclude that ...', 'I would suggest that ...', 'undeniably useful', 'above all', 'None of this means that ...; on the contrary, ...'],
      "Now that a phone can translate a menu or an email in seconds, it is tempting to conclude that learning a foreign language is no longer worth the effort. I would suggest that this view misunderstands what language learning is for. Translation software is undeniably useful for exchanging information, but communication involves far more than information. Humour, politeness and trust all depend on subtle choices that machines still handle clumsily, and a conversation conducted through a screen rarely leads to genuine friendship. Furthermore, studying another language offers benefits that have nothing to do with convenience: it trains the memory, sharpens awareness of one's own language and, above all, opens a window onto a different way of seeing the world. None of this means that technology should be rejected; on the contrary, it makes an excellent learning aid. Nevertheless, relying on it entirely would mean settling for being understood without ever really understanding others."),

    T('t07', 'complaint', '研修コースへの苦情',
      'You attended a three-day professional training course that was badly organised: sessions were cancelled and the promised materials never arrived. Write an email (120–180 words) to the course director explaining what went wrong and what you expect.',
      'あなたは3日間の職業研修に参加しましたが、運営がずさんでした（セッションの中止、約束された教材の未配布）。責任者に宛てて、問題点と求める対応を説明するメール（120～180語）を書いてください。',
      ['書き出しで用件（失望）と対象の研修を明示する', '広告内容と実際の違いを事実で示す', '求める対応（一部返金・教材送付）を具体的に書く', '期限を示し、丁寧だが毅然と結ぶ'],
      ['I am writing to express my disappointment with ...', 'at short notice', 'To make matters worse, ...', 'fell well short of ...', 'I trust that you will give this matter your prompt attention.'],
      "Dear Ms Hartley,\n\nI am writing to express my disappointment with the Advanced Project Management course which I attended from 4 to 6 March.\n\nAccording to your brochure, the course would be taught by experienced practitioners and would include practical workshops. In reality, two of the six sessions were cancelled at short notice, and the remaining workshops consisted largely of slides being read aloud. To make matters worse, the promised course materials were never distributed, despite repeated requests.\n\nGiven that my employer paid £900 for my place, I feel that the course fell well short of what was advertised. I would therefore be grateful if you could arrange a partial refund covering the cancelled sessions and send me the materials without further delay.\n\nI trust that you will give this matter your prompt attention, and I look forward to hearing from you within the next two weeks.\n\nYours sincerely,\nKenji Mori"),
    T('t08', 'complaint', '暖房の修理が進まない',
      'The heating in your rented flat has been broken for three weeks, and the property management company has ignored your calls. Write an email (120–180 words) to the manager.',
      '賃貸アパートの暖房が3週間故障したままで、管理会社は電話に対応してくれません。管理責任者に宛ててメール（120～180語）を書いてください。',
      ['用件と物件を1文で特定する', 'これまでの経緯を日付・回数とともに述べる', '契約上の根拠を示し、期限付きで対応を求める', '対応がない場合の次の手段を冷静に伝える'],
      ['I am writing with regard to ...', 'on four separate occasions', 'As you will appreciate, ...', 'I must therefore ask you to ...', 'I will have no alternative but to ...'],
      "Dear Mr Collins,\n\nI am writing with regard to the heating in my flat at 14 Marlow Court, which has now been out of order for three weeks.\n\nI first reported the fault by telephone on 8 January and was assured that an engineer would call within forty-eight hours. Since then I have contacted your office on four separate occasions, yet no one has come, and my last two messages have gone unanswered. As you will appreciate, living without heating in midwinter is not merely uncomfortable but potentially harmful to health.\n\nUnder the terms of my tenancy agreement, essential repairs are to be carried out promptly. I must therefore ask you to send an engineer by the end of this week and to confirm the appointment in writing. Should the problem remain unresolved, I will have no alternative but to seek advice from the local housing authority.\n\nI hope this will not prove necessary.\n\nYours sincerely,\nAya Tanaka"),
    T('t09', 'complaint', '航空会社の荷物遅延',
      'Your suitcase arrived five days late after a flight, and you had to buy essentials during a business trip. Write an email (120–180 words) to the airline asking for compensation.',
      '搭乗後、スーツケースの到着が5日遅れ、出張中に必需品を購入せざるを得ませんでした。航空会社に補償を求めるメール（120～180語）を書いてください。',
      ['便名・日付・予約番号を示して用件を述べる', '起きたことを時系列で簡潔に説明する', '最も不満な点を1つ強調する', '請求内容と回答期限を明示する'],
      ['I am writing to complain about ...', 'It did not in fact arrive until ...', 'I had no choice but to ...', 'reimburse these expenses in full', 'I would also appreciate an explanation of ...'],
      "Dear Customer Relations Team,\n\nI am writing to complain about the handling of my luggage on flight NA417 from Osaka to Manchester on 12 May (booking reference QX7R2L).\n\nOn arrival, my suitcase was missing, and I was told that it would be delivered to my hotel the following day. It did not in fact arrive until five days later, by which time my business trip was almost over. In the meantime I had no choice but to buy clothing and other essentials at a cost of £240. What I found most frustrating, however, was that your helpline was unable to give me any reliable information throughout.\n\nI enclose copies of my receipts and would ask you to reimburse these expenses in full. I would also appreciate an explanation of why the delay occurred and why I was not kept informed.\n\nI look forward to receiving your reply within fourteen days.\n\nYours faithfully,\nHiroshi Sato"),

    T('t10', 'request', '無給休暇の願い出',
      'You would like to take three months of unpaid leave to attend a course abroad. Write an email (120–180 words) to your manager making the request.',
      '海外の講座に参加するため、3か月の無給休暇を取りたいと考えています。上司に依頼するメール（120～180語）を書いてください。',
      ['依頼内容（期間・目的）を最初に明確に述べる', '業務への影響を抑える具体策を示す', 'チームにとっての利点を述べる', '面談を申し出て、感謝で結ぶ'],
      ['I am writing to ask whether it would be possible to ...', 'I realise that this is a considerable request', 'kept to a minimum', 'of direct benefit to ...', 'I would welcome the opportunity to discuss ...'],
      "Dear Ms Okafor,\n\nI am writing to ask whether it would be possible for me to take three months' unpaid leave from April to June next year in order to attend an intensive data analysis programme in Edinburgh.\n\nI realise that this is a considerable request, and I have given some thought to how any disruption might be kept to a minimum. The second quarter is traditionally our quietest period, and my current projects are due to be completed by the end of March. In addition, I would be happy to prepare detailed handover notes and to brief whoever covers my responsibilities.\n\nI firmly believe that the skills I would gain would be of direct benefit to the team, particularly as we are planning to expand our reporting work.\n\nI would welcome the opportunity to discuss this with you in person at your convenience. Thank you in advance for considering my request.\n\nKind regards,\nMika Hayashi"),
    T('t11', 'request', '面識のない専門家への講演依頼',
      'You are organising a small conference for young professionals. Write an email (120–180 words) to an expert you have never met, inviting her to give a talk.',
      'あなたは若手社会人向けの小さな会議を企画しています。面識のない専門家に講演を依頼するメール（120～180語）を書いてください。',
      ['誰として・何を依頼するのかを最初に述べる', 'なぜその人なのか（研究と会議テーマの関係）を説明する', '条件（費用・謝礼・代替案）を示す', '相手の多忙さに配慮し、回答期限を伝える'],
      ['I am writing on behalf of ...', 'whether you would consider ...ing', 'We would, of course, cover ...', 'Should the date prove inconvenient, ...', 'I would be most grateful if you could let me know ...'],
      "Dear Professor Lindqvist,\n\nI am writing on behalf of the Kansai Young Professionals Network to ask whether you would consider giving the opening talk at our annual conference, which will take place in Kobe on Saturday 18 October.\n\nThis year's theme is 'Working across cultures', and your research on communication in international teams has been widely read and discussed among our members. We believe that a forty-minute talk from you, followed by questions, would set exactly the right tone for the day.\n\nWe would, of course, cover your travel and accommodation, and we are able to offer a modest fee. Should the date prove inconvenient, we would be delighted to arrange a talk by video link instead.\n\nI appreciate that you must receive many invitations of this kind, and I would be most grateful if you could let me know by the end of June whether this might be possible.\n\nYours sincerely,\nDaichi Kimura"),
    T('t12', 'request', '元上司への推薦状依頼',
      'You are applying for a part-time master\'s programme and need a reference from a former supervisor. Write an email (120–180 words) asking for it.',
      '社会人向け修士課程に出願するため、以前の上司からの推薦状が必要です。依頼のメール（120～180語）を書いてください。',
      ['近況と感謝に軽く触れてから本題に入る', '何のための推薦状か、なぜその人に頼むのかを述べる', '締め切り・分量・添付資料を伝えて負担を減らす', '断りやすい余地を残して結ぶ'],
      ['I hope this message finds you well.', 'I am writing to ask a favour.', 'no one better placed to ...', 'To save you time, ...', 'I fully understand if ...'],
      "Dear Dr Whitfield,\n\nI hope this message finds you well. It has been two years since I left the marketing team, and I still draw daily on what I learned under your supervision.\n\nI am writing to ask a favour. I am applying for a part-time master's programme in business analytics at the University of Leeds, and the application requires a reference from someone who has supervised my work. Given that you oversaw the customer survey project, which I intend to describe in my application, I can think of no one better placed to comment on my abilities.\n\nThe reference should be submitted online by 30 November and need not exceed one page. To save you time, I have attached my CV and a short summary of the projects we worked on together.\n\nI fully understand if your schedule does not allow this, and I would be grateful for a reply either way.\n\nWith best wishes,\nYuki Nakamura"),

    T('t13', 'proposal', '新入社員メンター制度の提案',
      'Staff turnover among new employees is high at your company. Write an email (120–180 words) to your manager proposing a mentoring scheme.',
      'あなたの会社では新入社員の離職率が高くなっています。上司にメンター制度を提案するメール（120～180語）を書いてください。',
      ['提案のきっかけと内容を1文で示す', '現状の問題を根拠（新人の声）とともに説明する', '提案の具体的な仕組みと小規模な試行を示す', '次のステップを申し出て結ぶ'],
      ['I would like to put forward a proposal for ...', 'At present, ...', 'I propose that each ... be paired with ...', 'A pilot would allow us to ...', 'should the idea be of interest to you'],
      "Dear Mr Bennett,\n\nFollowing our conversation last week about staff turnover, I would like to put forward a proposal for a mentoring scheme for new employees.\n\nAt present, newcomers receive two days of formal training and are then largely left to find their own way. Feedback from recent recruits suggests that many feel reluctant to ask questions, which slows their progress and, in some cases, contributes to their decision to leave within the first year.\n\nI propose that each new member of staff be paired with an experienced colleague from a different team for their first six months. The pair would meet for thirty minutes every fortnight, at no cost other than time. A pilot involving this autumn's eight recruits would allow us to judge the results before committing ourselves further.\n\nI would be glad to draw up a more detailed plan should the idea be of interest to you.\n\nBest regards,\nSana Ito"),
    T('t14', 'proposal', '空き駐車場を地域の庭園に',
      'A car park near your home has been unused for years. On behalf of a residents\' group, write an email (120–180 words) to a local councillor proposing that it be turned into a community garden.',
      '自宅近くの駐車場が何年も使われていません。住民団体を代表して、そこを地域の共同庭園にすることを地元議員に提案するメール（120～180語）を書いてください。',
      ['誰を代表して何を提案するのかを述べる', '現状の問題と地域のニーズを説明する', '住民側と行政側の役割分担を明確にする', '実現性の根拠（資金・他の事例）を示し、説明の機会を求める'],
      ['I am writing on behalf of ... to propose that ... be converted into ...', 'at some cost to the council', 'Under our proposal, ...', 'We have already secured ...', 'We would welcome the chance to ...'],
      "Dear Councillor Reid,\n\nI am writing on behalf of the Elm Street Residents' Association to propose that the disused car park behind the library be converted into a community garden.\n\nThe site has stood empty since 2021 and has become a target for fly-tipping, at some cost to the council. Meanwhile, our neighbourhood has very little green space, and many residents, particularly elderly people living alone, have few places to meet.\n\nUnder our proposal, volunteers would build raised beds and maintain the garden, while the council would be asked only to grant a five-year lease and provide a water supply. Similar projects elsewhere in the city have reduced anti-social behaviour and proved popular with local schools.\n\nWe have already secured pledges of £3,000 from local businesses. We would welcome the chance to present the plan in more detail at the next committee meeting.\n\nYours sincerely,\nEmi Kondo\nChair, Elm Street Residents' Association"),
    T('t15', 'proposal', '週4日勤務の試行提案',
      'Your department suffers from high levels of sick leave and exhaustion. Write an email (120–180 words) to the HR director proposing a trial of a four-day working week.',
      'あなたの部署では病欠や疲弊が目立っています。人事部長に宛てて、週4日勤務の試行を提案するメール（120～180語）を書いてください。',
      ['提案内容（部署・期間）を最初に述べる', '問題の現状と他社の試行結果を根拠にする', '運用方法と成果の測り方を具体的に示す', 'リスクを認めたうえで自信を示し、面談を申し出る'],
      ['As you are aware, ...', 'citing exhaustion', 'Under the proposed arrangement, ...', 'namely ...', 'I recognise that there are risks involved; ... however, ...'],
      "Dear Ms Alvarez,\n\nI am writing to propose that the Customer Support department take part in a six-month trial of a four-day working week.\n\nAs you are aware, our team has experienced high levels of sick leave over the past year, and three experienced colleagues have left, citing exhaustion. Trials carried out by comparable organisations indicate that shorter weeks can reduce absence considerably without any loss of output.\n\nUnder the proposed arrangement, staff would work four slightly longer days, with days off staggered so that the helpline remains fully staffed from Monday to Friday. Performance would be monitored using our existing measures, namely response times and customer satisfaction scores, and the trial could be halted at any point should standards slip.\n\nI recognise that there are risks involved; I am confident, however, that a carefully monitored trial would enable us to assess them. I would be happy to discuss the details whenever suits you.\n\nKind regards,\nRen Fujita"),

    T('t16', 'report', '社員食堂アンケートの報告',
      'Your company surveyed 214 staff about the canteen. Findings: 71% think prices are reasonable; 62% are unhappy with the variety; few vegetarian options; queues of up to 20 minutes at peak times. Write a report summary (120–180 words) with recommendations.',
      '会社が社員214人に食堂についてアンケートを行いました。結果：71％が価格は妥当と回答、62％がメニューの種類に不満、ベジタリアン向けが少ない、混雑時は最大20分の行列。提言を含む報告の要約（120～180語）を書いてください。',
      ['1文目で報告の目的と調査規模を示す', '肯定的な結果と否定的な結果を対比して述べる', '最も多かった問題を強調する', '結果に基づく提言を2つ、番号立てて示す'],
      ['The purpose of this report is to ...', 'Overall, opinion was divided.', 'attracted particular criticism', 'In the light of these findings, ...', 'at relatively little cost'],
      "The purpose of this report is to summarise the findings of last month's staff survey on the canteen and to recommend improvements. A total of 214 employees responded.\n\nOverall, opinion was divided. While a clear majority (71%) considered prices reasonable, almost two thirds expressed dissatisfaction with the range of dishes on offer. The lack of vegetarian options attracted particular criticism, and a number of respondents commented that the menu had barely changed in a year. The most frequently mentioned problem, however, was queuing: at peak times, staff reported waiting up to twenty minutes, leaving little time to eat.\n\nIn the light of these findings, two measures are recommended. Firstly, the menu should be rotated weekly and include at least two vegetarian dishes each day. Secondly, a pre-ordering system would help to spread demand more evenly across the lunch period. Both changes could be introduced at relatively little cost."),
    T('t17', 'report', '業界カンファレンス参加報告',
      'You attended an industry conference on behalf of your team. Write a short report (120–180 words) for colleagues summarising what was useful and recommending what the team should do next.',
      'あなたはチームを代表して業界のカンファレンスに参加しました。有益だった点をまとめ、チームが次に取るべき行動を提言する短い報告（120～180語）を同僚向けに書いてください。',
      ['報告の目的と会議の概要を1文で示す', '主要テーマと、そこから得た要点を述べる', '役に立ったセッションと立たなかったものを対比する', '具体的な行動を提言して締める'],
      ['This report outlines ...', 'The dominant theme was ...', 'A recurring note of caution concerned ...', 'by far the most relevant', 'I would recommend that we ...'],
      "This report outlines the main points of interest from the Digital Retail Forum, held in Singapore on 9 and 10 September, and suggests how our team might act on them.\n\nThe dominant theme was the use of customer data to personalise services. Several speakers demonstrated that even modest personalisation, such as tailored reminders, can raise repeat purchases significantly. A recurring note of caution, however, concerned privacy: companies that collect data without explaining why risk losing their customers' trust.\n\nOf the workshops, the session on small-scale testing was by far the most relevant to us. Its central message was that trying out ideas on a few hundred customers is both cheaper and more reliable than large launches. The session on virtual reality, by contrast, was of little practical value.\n\nI would recommend that we pilot personalised reminders with a small customer group next quarter and review our privacy notice beforehand. Slides are available on request."),
    T('t18', 'report', 'フレックス始業の試行結果',
      'Your office ran a six-month trial of flexible start times. Results: 80% of staff report better work–life balance; lateness fell by almost half; meetings became harder to schedule. Write a report summary (120–180 words) saying whether the scheme should continue.',
      'あなたの職場で始業時間のフレックス制を6か月試行しました。結果：80％がワークライフバランスの改善を実感、遅刻はほぼ半減、会議の日程調整は難しくなった。制度を継続すべきかを述べる報告の要約（120～180語）を書いてください。',
      ['報告の目的（評価と継続の可否）を示す', '全体評価と、それを支える数値を述べる', '問題点を公平に記述する', '条件付きの提言と見直し時期を示す'],
      ['This report evaluates ...', 'On the whole, ... can be regarded as a success.', 'it would be premature to attribute this entirely to ...', 'was not without its drawbacks', 'It is therefore recommended that ... be retained, subject to ...'],
      "This report evaluates the six-month trial of flexible start times in the Osaka office and considers whether the scheme should be made permanent.\n\nOn the whole, the trial can be regarded as a success. Four out of five employees said that the arrangement had improved their work–life balance, and lateness, previously a persistent problem, fell by almost half. Managers also noted a slight rise in output, although it would be premature to attribute this entirely to the new hours.\n\nThe scheme was not without its drawbacks. Because staff arrived at different times, meetings proved difficult to schedule, and some teams complained that colleagues were unavailable when needed. Customer-facing departments were particularly affected.\n\nIt is therefore recommended that flexible start times be retained, subject to one condition: all staff should be present between 10 a.m. and 3 p.m., so that meetings and client calls can be concentrated within these core hours. The policy should be reviewed after twelve months."),

    T('t19', 'review', 'ビジネス書のレビュー',
      'Write a review (120–180 words) of a non-fiction book for your company newsletter. Say what the book argues, what it does well, where it is weak, and who should read it.',
      '社内報向けに、ノンフィクションの本のレビュー（120～180語）を書いてください。本の主張、優れた点、弱い点、誰に薦めるかを述べること。',
      ['評価を含む1文で読者の関心を引き、本の主張を示す', '優れた点を具体例とともに述べる', '弱点を公平に指摘する', '誰に薦めるかを明確にして締める'],
      ['Few books manage to be both ... and ...', 'Its central claim is deceptively simple: ...', 'The book is not without its weaknesses.', 'feels thin by comparison', 'a thought-provoking read'],
      "Few books about work manage to be both rigorous and readable, but 'The Quiet Hours' by Laura Menzies comes close. Its central claim is deceptively simple: most of us spend our days reacting to messages rather than doing the work we are actually paid for.\n\nMenzies, a former consultant, builds her case through a series of vivid case studies, the most memorable of which describes a law firm that banned internal email on Fridays, with surprising results. She writes with dry humour and wisely avoids the breathless tone that spoils so many business titles.\n\nThe book is not without its weaknesses. The final third, which offers practical advice, feels thin by comparison, and readers who have little control over their own schedules may find some suggestions unrealistic.\n\nNevertheless, this is a thought-provoking read which I would recommend to anyone who ends the day wondering where the time went. Managers, in particular, should take note."),
    T('t20', 'review', 'オンライン講座のレビュー',
      'Write a review (120–180 words) of an online course you have taken, for a website where professionals share learning recommendations.',
      '社会人が学習のおすすめを共有するサイト向けに、受講したオンライン講座のレビュー（120～180語）を書いてください。',
      ['受講前の期待と全体評価を示す', '講座の構成と、他と違う長所を述べる', '欠点（負担・価格）を具体的に指摘する', '誰に向いていて誰に向かないかで締める'],
      ['with modest expectations', 'What sets it apart is ...', 'That said, ... is not flawless.', 'considerably heavier than advertised', 'On balance, though, ...'],
      "Having tried several online courses with mixed results, I enrolled on 'Data Skills for Beginners' with modest expectations. To my surprise, it turned out to be one of the most worthwhile things I have done this year.\n\nThe eight-week course assumes no prior knowledge and is built around short video lessons, each followed by a practical exercise using real data. What sets it apart is the quality of the feedback: assignments are marked by tutors, not software, and their comments are detailed and encouraging. The discussion forum is also unusually lively.\n\nThat said, the course is not flawless. The workload in the second half is considerably heavier than advertised, and anyone with a full-time job should expect to give up their weekends. At £280, it is hardly cheap either.\n\nOn balance, though, the course delivers what it promises. I would recommend it to anyone prepared to make the commitment; those seeking a casual introduction should look elsewhere."),
    T('t21', 'review', 'ドキュメンタリー映画のレビュー',
      'Write a review (120–180 words) of a documentary or film you have seen recently, for an English-language magazine read by international residents.',
      '外国人居住者向けの英字誌に、最近観たドキュメンタリーまたは映画のレビュー（120～180語）を書いてください。',
      ['作品の紹介と、意外性のある全体評価で始める', '内容と見どころを具体的な場面で伝える', '弱点を認める（Admittedly, ...）', '余韻のある一文と推薦で締める'],
      ['not an obvious crowd-pleaser', 'without resorting to ...', 'genuinely moving', 'Admittedly, ... demands patience', 'well worth seeking out'],
      "'Salt Roads', a documentary about the last family of salt makers on a remote stretch of the Japanese coast, is not an obvious crowd-pleaser. It has no narrator, very little music and a pace that could kindly be described as unhurried. It is also quietly remarkable.\n\nOver ninety minutes, the director follows three generations through a single year, allowing the family's doubts about the future to emerge gradually through small, telling moments, without resorting to interviews. The photography is stunning, and a scene in which the grandfather teaches his reluctant grandson to read the weather is genuinely moving.\n\nAdmittedly, the film demands patience, and some viewers will wish that it explained more about the economics that are driving such trades to extinction. The ending, too, feels rather abrupt.\n\nEven so, 'Salt Roads' lingers in the mind long after it ends. For anyone curious about how traditions disappear, it is well worth seeking out."),

    T('t22', 'counter', '「会議は時間の無駄」への反論',
      'A colleague claims: "Meetings are a waste of time and should be replaced by email." Write a paragraph (120–180 words) that acknowledges the point and then argues against it.',
      '同僚が「会議は時間の無駄で、メールに置き換えるべきだ」と主張しています。その点を一部認めたうえで反論する1段落（120～180語）を書いてください。',
      ['相手の主張を公平に紹介する（It is often claimed that ...）', '正しい部分を具体的に認める', 'It does not follow, however, ... で反論に転じ、理由を2つ述べる', '相手の本当の不満を言い直し、代案で締める'],
      ['It is often claimed that ...', 'There is undoubtedly some truth in this: ...', 'It does not follow, however, that ...', 'Nor can ...', 'What the critics are really objecting to is ...'],
      "It is often claimed that meetings are a waste of time and that everything they achieve could be accomplished by email. There is undoubtedly some truth in this: many meetings are too long, poorly prepared and attended by people who have no reason to be there. It does not follow, however, that meetings as such are the problem. Written messages are well suited to passing on information, but they are a poor tool for resolving disagreements, since tone is easily misread and a discussion that would take ten minutes face to face can drag on for days. Nor can email replace the sense of shared responsibility that emerges when a decision is reached together. What the critics are really objecting to, I would suggest, is bad meetings rather than meetings in general. The sensible response is therefore to hold fewer of them, with a clear agenda and a fixed time limit, not to abolish them altogether."),
    T('t23', 'counter', '「動物園は全廃すべき」への反論',
      'Some people claim: "Zoos are cruel and should all be closed." Write a paragraph (120–180 words) that acknowledges the point and then argues against it.',
      '「動物園は残酷であり、すべて閉鎖すべきだ」と主張する人がいます。その点を一部認めたうえで反論する1段落（120～180語）を書いてください。',
      ['反対派の主張を正確に要約する', '認めるべき事実を挙げる（there is no denying that ...）', '結論が行きすぎである理由を2～3点述べる', 'より妥当な要求を示して締める'],
      ['This argument deserves to be taken seriously, for ...', 'there is no denying that ...', 'Nevertheless, the conclusion goes too far.', 'may well shape ...', 'A more reasonable demand, surely, is that ...'],
      "Opponents of zoos argue that keeping wild animals in captivity is inherently cruel and that all zoos should therefore be closed. This argument deserves to be taken seriously, for there is no denying that some animals, notably elephants and large predators, suffer in confined spaces, and that many zoos in the past existed purely for entertainment. Nevertheless, the conclusion goes too far. Modern zoos play a role in conservation that would be hard to replace: several species which had died out in the wild survive today only because of captive breeding programmes. Zoos also fund research and give millions of city children their first real encounter with wildlife, which may well shape their attitudes to nature in later life. Closing every zoo would do nothing for the animals already in them, most of which could not survive if released. A more reasonable demand, surely, is that zoos be held to far stricter standards and that those failing to meet them be shut down."),
    T('t24', 'counter', '「宿題は廃止すべき」への反論',
      'Some parents claim: "Homework does nothing for learning and should be abolished." Write a paragraph (120–180 words) that acknowledges the point and then argues against it.',
      '「宿題は学習の役に立たないので廃止すべきだ」と主張する保護者がいます。その点を一部認めたうえで反論する1段落（120～180語）を書いてください。',
      ['主張を紹介し、懸念はもっともだと認める', '研究が示す事実を公平に述べる', '見落とされている区別（質の違い）を指摘して反論する', '「なくす」ではなく「減らして良くする」で締める'],
      ['Their concerns are understandable.', 'Research indicates that ...', 'To conclude that ..., however, is to overlook ...', 'by contrast', 'The solution, I would argue, lies in ...'],
      "A growing number of parents and teachers maintain that homework contributes little to learning and ought to be abolished. Their concerns are understandable. Research indicates that, for younger children in particular, the academic benefits of homework are slight, while the cost in terms of stress and lost free time can be considerable. To conclude that all homework is pointless, however, is to overlook an important distinction. The evidence against it relates largely to repetitive tasks set out of habit; well-designed assignments, by contrast, appear to bring real benefits for older pupils, especially when they involve reading or independent research that cannot easily be done in class. Homework also gives pupils practice in managing their own time, a skill on which later study depends. Abolition would, moreover, widen the gap between children whose parents arrange extra tuition and those whose parents cannot. The solution, I would argue, lies in setting less homework but better homework, rather than none at all.")
  ];

  /* ---------- readings ---------- */
  var readings = [
    { id: 'r01', title: 'The Open-Plan Promise',
      text: "When our company tore down its office walls last spring, the announcement spoke of 'spontaneous collaboration' and 'a culture of openness'. Six months on, the collaboration is certainly spontaneous: I can now follow three conversations at once, none of which concerns me. Colleagues who once dropped by with a question have taken to sending messages instead, apparently reluctant to be overheard by forty people. Headphones, meanwhile, have become the new office door. Management points out that the new layout saves a considerable sum in rent, a benefit which, curiously, did not feature in the original announcement. I do not doubt that open offices suit some kinds of work. But if the aim was to get us talking, it is worth noting that the liveliest discussions now take place in the one room that still has walls: the kitchen.",
      ja: '会社は「協働」と「開放性」を掲げてオフィスの壁を取り払ったが、実際には会話が減り、社員はヘッドホンで自分を守っている。筆者は、本当の動機は賃料の節約だったのではないかとほのめかしている。',
      qs: [
        { q: "What does the writer imply by saying that the saving in rent 'curiously, did not feature in the original announcement'?",
          options: ['Management forgot to mention an important benefit.', 'Cost-cutting was probably the real reason for the change.', 'The saving turned out to be smaller than expected.', 'Staff were told about the saving in a separate meeting.'],
          answer: 1, why: 'curiously（奇妙なことに）は皮肉です。公式発表の「協働」は建前で、実際の動機は経費削減だったのではないかという疑いを示しています。' },
        { q: "What does 'Headphones have become the new office door' suggest?",
          options: ['Staff now listen to music instead of working.', 'The company has provided headphones to all employees.', 'People use headphones to shut out others, as a door once did.', 'Offices with doors are noisier than open-plan ones.'],
          answer: 2, why: 'ドアは「邪魔しないで」という合図でした。壁がなくなった今、ヘッドホンがその役割を果たしている、つまり開放的な空間が逆に人を閉じこもらせている、という含みです。' }
      ],
      summaryModel: 'The writer suggests that the open-plan office, introduced in the name of collaboration, has actually reduced conversation and was probably motivated by cost.' },
    { id: 'r02', title: 'The Cult of Measurement',
      text: "There is now an app for every minute of the day. One tracks my sleep, another rations my screen time, and a third congratulates me, with a small burst of confetti, for drinking water. The promise is always the same: measure your life and you will master it. Yet the friends of mine who measure most seem, if anything, the least at ease. A walk is no longer a walk but a step count; a book is a target to be met by Friday. What troubles me is not the technology, which is harmless enough, but the assumption behind it: that an hour which produces nothing has been wasted. Some of my best ideas have arrived while I was staring out of a train window, achieving, by any measurable standard, absolutely nothing. I have yet to find the app that would have counted that.",
      ja: '生活のあらゆることを数値化するアプリが増えているが、熱心に測る人ほど落ち着きを失っているように見える。筆者は「何も生まない時間は無駄だ」という前提そのものに疑問を投げかけている。',
      qs: [
        { q: "What is the writer's attitude towards the app that 'congratulates me, with a small burst of confetti, for drinking water'?",
          options: ['Gently mocking', 'Sincerely grateful', 'Deeply alarmed', 'Entirely neutral'],
          answer: 0, why: '水を飲んだだけで紙吹雪で祝われる、という描写は大げささを面白がる軽い皮肉です。後で the technology is harmless enough と述べているので、強い警戒ではありません。' },
        { q: "In the final sentence, what does 'that' refer to?",
          options: ['The number of train journeys the writer makes', 'The time the writer wastes on apps', 'The step count recorded during a walk', 'The value of apparently unproductive time spent daydreaming'],
          answer: 3, why: 'that は直前の「車窓を眺めて、測定上は何もしていない時間（に良い考えが浮かんだこと）」を指します。アプリでは測れない価値がある、という結論です。' }
      ],
      summaryModel: 'The writer argues that tracking apps rest on the mistaken belief that unmeasured, unproductive time is wasted, when idleness often produces our best ideas.' },
    { id: 'r03', title: "The Tourist's Complaint",
      text: "Every summer, the same complaint is heard in the world's most beautiful cities: there are too many tourists. Remarkably, it is often voiced by tourists themselves, who seem to regard everyone else in the queue as an intruder on their own, more authentic, visit. We want the empty piazza we saw in the photograph, forgetting that the photographer got up at five in the morning and waited for the crowds to clear. Cities, for their part, are hardly innocent. Having spent decades and fortunes advertising their charms, some now express astonishment that people have come. None of this is to deny that overcrowding does real damage, or that residents priced out of their own neighbourhoods have every right to be angry. But a little honesty would help. The problem with tourism is not other people. It is all of us, and the bill has merely arrived.",
      ja: '観光客が多すぎるという不満は、しばしば観光客自身から出てくる。筆者は、宣伝を重ねてきた都市も含め、問題の原因は「他人」ではなく私たち全員にあると指摘している。',
      qs: [
        { q: 'How does the writer view tourists who complain about the number of tourists?',
          options: ['As people with a reasonable grievance', 'As more respectful than ordinary visitors', 'As failing to see that they are part of the problem', 'As victims of misleading photographs'],
          answer: 2, why: 'Remarkably や their own, more authentic, visit という言い方に皮肉が込められています。自分だけは「本物の旅行者」だと考え、自分も混雑の一部であることに気づいていない、という見方です。' },
        { q: "What does the writer mean by saying that cities 'are hardly innocent'?",
          options: ['They helped to create the crowds by promoting themselves.', 'They treat tourists dishonestly.', 'They have broken laws protecting residents.', 'They exaggerate the damage caused by tourism.'],
          answer: 0, why: '直後の文で、長年大金をかけて魅力を宣伝しておきながら、人が来たことに驚いている、と述べています。都市自身にも責任があるという意味です。' }
      ],
      summaryModel: 'The writer argues that overtourism is a problem created by everyone, including complaining tourists and the cities that advertised for visitors.' },
    { id: 'r04', title: 'The Lecture Survives',
      text: "For at least thirty years, experts have been predicting the death of the university lecture. It is, we are told, a relic: one person talking while two hundred others pretend to listen. Videos can be paused, repeated and watched at double speed; why would anyone travel across town to sit on a hard seat? And yet the lecture halls remain stubbornly full. I suspect the experts have misjudged what students come for. Few of them, in my experience, attend in order to receive information, which they know perfectly well is available online. They come because being in a room with others who are trying to understand the same thing makes the effort feel worthwhile, and because a lecturer who thinks aloud, hesitates and changes her mind is showing them something no polished video can. Efficiency, it turns out, was never quite the point.",
      ja: '大学の講義は時代遅れだと長年言われてきたが、教室は今も満員である。筆者は、学生が求めているのは情報ではなく、共に学ぶ場と、考える過程を目の前で見ることだと考えている。',
      qs: [
        { q: "What is the writer's attitude towards the experts' predictions?",
          options: ['They were right, but ahead of their time.', 'They rest on a misunderstanding of why students attend.', 'They were made by people who dislike technology.', 'They have recently started to come true.'],
          answer: 1, why: 'I suspect the experts have misjudged what students come for と述べています。専門家は講義を「情報伝達」と捉えたが、学生が来る理由は別にある、という立場です。' },
        { q: "What is the 'something no polished video can' show?",
          options: ['Information that is not available online', 'The mistakes that lecturers often make', 'How to study more efficiently', 'The real, untidy process of thinking a problem through'],
          answer: 3, why: 'thinks aloud, hesitates and changes her mind（声に出して考え、迷い、考えを変える）とあり、編集済みの動画では見えない「思考の生の過程」を指しています。' }
      ],
      summaryModel: 'The writer believes lectures survive because students value shared effort and watching real thinking, not the efficient delivery of information.' },
    { id: 'r05', title: 'The Kindness of Algorithms',
      text: "My music app knows me alarmingly well. Each Monday it presents a playlist chosen 'just for me', and each Monday I am obliged to admit that it is rather good. The songs resemble those I already like, only slightly different, in the way that one hotel breakfast resembles another. That, I have come to think, is precisely the trouble. Looking back, the records which mattered most to me were ones I disliked at first: a friend insisted, I resisted, and somewhere around the fifth listen something gave way. No algorithm would have taken that risk on my behalf; its entire purpose is to spare me the experience of not enjoying myself. I am grateful for the convenience, in the way one is grateful for a comfortable chair. But I notice that I have not been surprised in quite some time, and I am beginning to miss it.",
      ja: '音楽アプリのおすすめは確かに心地よいが、どれも似通っている。筆者は、最初は嫌いだった曲こそが後に大切になった経験を振り返り、驚きが失われたことを物足りなく感じている。',
      qs: [
        { q: 'What does the comparison with a hotel breakfast suggest about the recommended songs?',
          options: ['They are expensive for what they offer.', 'They are best enjoyed in the morning.', 'They are pleasant enough but predictable.', 'They are of surprisingly high quality.'],
          answer: 2, why: 'ホテルの朝食はどこでも似たり寄ったりで、悪くはないが驚きもありません。おすすめの曲も「心地よいが予想どおり」だという含みです。' },
        { q: "Which best describes the writer's overall attitude to the app?",
          options: ['Appreciative, yet uneasy about what is being lost', 'Angry about the loss of privacy', 'Enthusiastic and uncritical', 'Indifferent to its recommendations'],
          answer: 0, why: 'grateful for the convenience と認めつつ、But I notice ... I am beginning to miss it と続けています。便利さへの感謝と、失われたものへの物足りなさが同居しています。' }
      ],
      summaryModel: 'Although the app\'s recommendations are reliably pleasant, the writer misses the surprise of music that is initially disliked and later comes to matter.' },
    { id: 'r06', title: 'Second-hand Virtue',
      text: "Buying second-hand clothes used to be a matter of necessity; these days it is a statement of principle. Resale apps assure us that every purchase 'saves' a quantity of water and carbon, helpfully calculated to the nearest gram. I have no wish to mock anyone for trying to consume less. I do wonder, though, whether less is really what is happening. Several people I know now buy more than they ever did, reasoning that a garment can always be sold on, and that shopping has therefore become a form of recycling. The clothes travel from wardrobe to wardrobe by courier, each journey wrapped in fresh plastic. Somewhere along the way, a sensible idea, namely keeping things in use for longer, has turned into a justification for never keeping anything for long at all. The planet, one imagines, is not much impressed by our clear consciences.",
      ja: '古着の売買は環境に良い行為とされているが、「また売ればいい」と考えて以前より多く買う人もいる。筆者は、長く使うという本来の考えが、消費を正当化する口実に変わっていると皮肉っている。',
      qs: [
        { q: "What is the effect of the phrase 'helpfully calculated to the nearest gram'?",
          options: ['It praises the apps for their scientific accuracy.', 'It shows the writer has checked the figures.', 'It explains how the savings are measured.', 'It casts ironic doubt on how meaningful such precise claims are.'],
          answer: 3, why: 'helpfully は皮肉です。グラム単位まで計算された「節約量」は、もっともらしく見えるだけで実態を表していないのではないか、という疑いを示しています。' },
        { q: 'What does the writer imply about resale apps?',
          options: ['They have made clothes more expensive.', 'They may be encouraging people to consume more, not less.', 'They are used mainly by people who cannot afford new clothes.', 'They will soon replace ordinary shops.'],
          answer: 1, why: '知人たちが「売ればいい」と考えて以前より多く買っている、と述べています。再販アプリが消費を減らすどころか増やしている可能性をほのめかしています。' }
      ],
      summaryModel: 'The writer suspects that resale apps, far from reducing consumption, give people a comfortable excuse to buy more clothes than ever.' },
    { id: 'r07', title: 'The Expert Problem',
      text: "It is commonly said that people have lost their faith in experts. I am not sure this is quite right. The same person who dismisses economists on a Monday will follow a surgeon's instructions to the letter on a Tuesday. What we distrust, it seems, is not expertise itself but expertise that tells us something we would prefer not to hear, particularly when it comes with a bill attached. Experts have not always helped their own cause. Too often, a cautious finding is announced as a certainty, and when the certainty collapses, the caution is forgotten and only the collapse is remembered. A little more 'we think' and a little less 'we know' might cost a few headlines, but it would be an investment worth making. Trust, after all, is seldom lost by admitting doubt. It is lost by being confidently wrong.",
      ja: '人々は専門家全般を信じなくなったのではなく、聞きたくないことを言う専門家を疑っているだけだと筆者は考える。同時に、専門家の側も不確かさを正直に示すべきだと主張している。',
      qs: [
        { q: 'Why does the writer mention the economist and the surgeon?',
          options: ['To show that distrust of experts is selective, not general', 'To argue that surgeons are more reliable than economists', 'To suggest that people trust experts less at the start of the week', 'To prove that expertise has become too specialised'],
          answer: 0, why: '同じ人が経済学者は退け、外科医には従う、という例は、専門家不信が全面的なものではなく、都合によって選択的であることを示しています。' },
        { q: 'What does the writer believe experts should do?',
          options: ['Avoid speaking to the media altogether', 'Present their findings with greater confidence', 'Be more open about the limits of what they know', 'Stop giving advice that costs people money'],
          answer: 2, why: "A little more 'we think' and a little less 'we know' とあり、不確かさを認める方が信頼を保てる、と主張しています。信頼を失うのは「自信満々で間違えること」だからです。" }
      ],
      summaryModel: 'The writer argues that distrust of experts is selective, and that experts would keep more trust by openly admitting uncertainty.' },
    { id: 'r08', title: 'Fast Internet, Slow Village',
      text: "The village where my grandmother grew up now has faster internet than my flat in the city, and with it has come a new kind of resident. They arrive with laptops and good intentions, rent the old houses that nobody wanted, and describe the place online as 'undiscovered', to the mild amusement of the nine hundred people who had already found it. It would be easy to sneer, and some of the locals do. Yet the bakery that was due to close has taken on two staff, and the primary school, for the first time in a decade, has a waiting list. Whether the newcomers will still be there after their second winter is another matter; enthusiasm for rural life has a way of fading along with the daylight. For the moment, though, the village is doing something it had almost forgotten how to do: making plans.",
      ja: '高速インターネットの整備により、祖母の故郷の村にリモートワーカーが移住してきた。筆者は彼らが定着するかには懐疑的だが、村に活気と将来への展望が戻ったことを前向きに評価している。',
      qs: [
        { q: "Why are the villagers amused by the word 'undiscovered'?",
          options: ['Because the village is actually a famous tourist destination', 'Because the newcomers cannot find their way around', 'Because the village is difficult to find on a map', 'Because it overlooks the people who have always lived there'],
          answer: 3, why: 'the nine hundred people who had already found it（すでにそこを「発見」していた900人）という言い方で、もともとの住民を無視した「未発見」という表現のおかしさを指摘しています。' },
        { q: "Which best describes the writer's attitude to the newcomers?",
          options: ['Openly hostile', 'Cautiously positive', 'Wholly enthusiastic', 'Completely indifferent'],
          answer: 1, why: '嘲笑するのは簡単だ（It would be easy to sneer）としつつ、Yet 以下で良い変化を挙げています。定着するかは疑問だが、今のところは歓迎すべきだ、という慎重な肯定です。' }
      ],
      summaryModel: 'Despite doubts about whether remote workers will stay, the writer welcomes the new life and optimism they have brought to the village.' },
    { id: 'r09', title: 'Five Stars for Everything',
      text: "I recently bought a kettle. Within an hour, I had received an email asking me to rate the experience; within a day, a second one wondering whether I had forgotten. The driver who delivered it also hoped for five stars, as, in due course, did the app through which I had paid. We are told that all this feedback empowers the customer, and no doubt it was once useful to know which restaurants to avoid. But when anything less than five stars is treated as a complaint, the scale ceases to mean anything: everything is excellent, and so nothing is. Worse, the burden falls on those least able to bear it. The driver cannot make the traffic move or the kettle better, yet it is his rating, not the company's, that suffers when I am in a bad mood. I gave him five stars. The kettle, for the record, is fine.",
      ja: 'あらゆる場面で星5つの評価を求められるようになり、評価そのものが意味を失っていると筆者は指摘する。しかもその負担は、自分ではどうにもできない配達員のような弱い立場の人にかかっている。',
      qs: [
        { q: "What does the writer mean by 'everything is excellent, and so nothing is'?",
          options: ['The quality of products has improved in recent years.', 'Customers have become too easy to please.', 'When top ratings are expected, ratings no longer tell us anything.', 'Companies delete reviews that are not excellent.'],
          answer: 2, why: '星5つ未満が「苦情」扱いされるなら、誰もが5をつけるしかなく、評価に差がなくなります。その結果、評価が情報としての価値を失う、という意味です。' },
        { q: 'Why, according to the text, did the writer give the driver five stars?',
          options: ['Because it seemed unfair for him to be punished for things beyond his control', 'Because the delivery was exceptionally fast', 'Because the company required it', 'Because the kettle was better than expected'],
          answer: 0, why: '配達員は渋滞も商品の質も変えられないのに、評価が下がって困るのは本人だ、と述べています。その不公平さを避けるために5をつけた、と読み取れます。' }
      ],
      summaryModel: 'The writer argues that constant demands for five-star ratings have made ratings meaningless while unfairly burdening low-paid workers.' },
    { id: 'r10', title: 'Learning to Be Bad at Something',
      text: "At the age of forty-three, I have taken up the cello, and I am terrible at it. This is not modesty. My teacher, a patient woman of twenty-six, has a way of saying 'interesting' that leaves little room for doubt. What has surprised me is how much I had forgotten about being a beginner. In my working life I am, by now, reasonably competent, and competence is a comfortable place from which to judge others. I had become quick to wonder why junior colleagues needed things explained twice. An hour a week of producing sounds that distress the neighbours has cured me of that. I doubt I shall ever play well. But I have come to suspect that adults should be required to be bad at something on a regular basis, if only to remember what it costs to ask for help.",
      ja: '43歳でチェロを始めた筆者は、自分の下手さを通じて初心者の気持ちを思い出した。有能であることに慣れると他人に厳しくなるため、大人は定期的に「下手なこと」に取り組むべきだと考えている。',
      qs: [
        { q: "What does the teacher's way of saying 'interesting' imply?",
          options: ['She finds the writer an unusually gifted student.', "She is politely signalling that the playing is poor.", 'She is curious about why the writer chose the cello.', 'She has lost interest in teaching.'],
          answer: 1, why: "leaves little room for doubt（疑いの余地がほとんどない）とあり、直前で I am terrible at it. This is not modesty. と述べています。'interesting' は下手さを遠回しに伝える婉曲表現です。" },
        { q: "What does 'that' refer to in 'has cured me of that'?",
          options: ['The fear of playing in front of others', 'The habit of practising too little', 'The wish to become a professional musician', 'Impatience with colleagues who need extra explanation'],
          answer: 3, why: '直前の文 I had become quick to wonder why junior colleagues needed things explained twice（後輩がなぜ二度説明を必要とするのかとすぐ思うようになっていた）を指しています。' }
      ],
      summaryModel: 'Being a hopeless beginner at the cello has reminded the writer how hard learning is and made them more patient with others.' }
  ];

